const tabId = 725789847;
await tool.navigate({ tabId, url: "https://www.entertainmentcareers.net/sbjobs/?state=NY" });
await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });

const jobs = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('.job-item, .list-item, article, tr, .job-listing, div.row'));
  // let's look for links to jobs
  const jobLinks = Array.from(document.querySelectorAll('a[href*="/job/"]')).map(a => {
    const parent = a.closest('div, tr, li') || a;
    return {
      title: a.textContent.trim(),
      url: a.href,
      text: parent.textContent.replace(/\s+/g, ' ').trim()
    };
  });
  return {
    title: document.title,
    count: jobLinks.length,
    jobs: jobLinks.slice(0, 30)
  };
});
console.log(JSON.stringify(jobs, null, 2));

