const tabId = 725789847;

const cats = [
  { name: "Distribution", url: "https://www.entertainmentcareers.net/jcat.asp?jcat=140&state=NY" },
  { name: "Development", url: "https://www.entertainmentcareers.net/jcat.asp?jcat=111&state=NY" },
  { name: "PostProduction", url: "https://www.entertainmentcareers.net/jcat.asp?jcat=121&state=NY" },
  { name: "Coordinator", url: "https://www.entertainmentcareers.net/jcat.asp?jcat=166&state=NY" }
];

const catResults = [];
for (const c of cats) {
  await tool.navigate({ tabId, url: c.url });
  await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 7000 });
  const list = await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll('a[href*="/job/"]')).map(a => ({
      title: a.innerText.trim(),
      href: a.href,
      text: (a.closest('tr, li, div') || a).innerText.replace(/\s+/g, ' ').trim()
    })).slice(0, 10);
  });
  catResults.push({ name: c.name, jobs: list });
}

console.log(JSON.stringify(catResults, null, 2));

