const urls = [
  "https://gala2327.applytojob.com/apply/0CJSlaL9so/Rental-Prep-Technician",
  "https://tribecafilm.applytojob.com/apply/YTzN2ETQDl/Shorts-Programmer-seasonal",
  "https://rooftopfilms.com/jobs/",
  "https://www.entertainmentcareers.net/nicolosi-and-co-inc/agency-assistant-tv-film-theater/job/531428/",
  "https://www.linkedin.com/jobs/view/production-assistant-at-newform-4445391730",
  "https://www.linkedin.com/jobs/view/cinema-junior-technician-at-adorama-4459370581"
];

const newTabs = [];
for (const url of urls) {
  const t = await tool.tabs_create({ url });
  await tool.wait_for({ tabId: t.details.tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 10000 });
  newTabs.push({ tabId: t.details.tabId, url });
}

console.log("Created tabs:", newTabs);

